{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-Qlfy82/src/path.js","content":"/**
 * A path is a list of segments, each either a table key (`{ key }`) or an
 * array index (`{ index }`), matching the format used both by error messages
 * ("<path> is not a table", "key <path> is defined twice", ...) and by the
 * `keys` output (object keys joined with `.`, array indices as `[i]`).
 */

export function keySeg(name) {
  return { key: name }
}

export function indexSeg(index) {
  return { index }
}

export function joinPath(segments) {
  let out = ''
  for (const seg of segments) {
    if ('key' in seg) {
      out += (out === '' ? '' : '.') + seg.key
    } else {
      out += '[' + seg.index + ']'
    }
  }
  return out
}
"}

