{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-Qlfy82/src/nodes.js","content":"/**
 * The value tree the parser builds. Every node carries a `kind`:
 *   'table'            -> { kind, children: Map<string, node>, headerDefined }
 *   'array-of-tables'  -> { kind, items: table[] }
 *   'array'            -> { kind, items: node[] }
 *   'string'|'integer'|'float'|'boolean' -> { kind, value }
 *
 * `headerDefined` tracks whether a bare `[name]` header has already made this
 * exact table current, which is what a second such header is forbidden to
 * repeat; tables that only came into being implicitly are unaffected.
 */

export function newTable() {
  return { kind: 'table', children: new Map(), headerDefined: false }
}
"}

