{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-Qlfy82/src/parser.js","content":"import { TomlError } from './errors.js'
import { newTable } from './nodes.js'
import { keySeg, indexSeg, joinPath } from './path.js'

const INT_RE = /^[+-]?[0-9]+(_[0-9]+)*$/
const FLOAT_RE = /^[+-]?[0-9]+(_[0-9]+)*(\.[0-9]+(_[0-9]+)*)?([eE][+-]?[0-9]+(_[0-9]+)*)?$/
const BARE_CHAR_RE = /[A-Za-z0-9_-]/

/**
 * Parses the whole document (already split into lines, with the empty tail
 * a trailing newline leaves already dropped) and returns the root table.
 * Throws a `TomlError` with `.line` set to the 1-based offending line.
 */
export function parseDocument(lines) {
  const root = newTable()
  const state = { currentTable: root, currentPath: [] }
  for (let i = 0; i < lines.length; i++) {
    try {
      processLine(lines[i], state)
    } catch (err) {
      if (err instanceof TomlError) {
        err.line = i + 1
      }
      throw err
    }
  }
  return root
}

// ---- line-level cursor helpers -------------------------------------------

function makeCursor(s) {
  return { s, i: 0, len: s.length }
}

/** Skips spaces/tabs, then treats a `#`/`;` outside a quote as "nothing more on this line". */
function skip(cur) {
  while (cur.i < cur.len && (cur.s[cur.i] === ' ' || cur.s[cur.i] === '\t')) cur.i++
  if (cur.i < cur.len && (cur.s[cur.i] === '#' || cur.s[cur.i] === ';')) cur.i = cur.len
}

function processLine(line, state) {
  const cur = makeCursor(line)
  skip(cur)
  if (cur.i >= cur.len) return // blank or comment-only line contributes nothing
  if (cur.s[cur.i] === '[') {
    handleHeader(cur, state)
  } else {
    handleAssignment(cur, state)
  }
}

// ---- names -----------------------------------------------------------------

function parseName(cur) {
  if (cur.i >= cur.len) throw new TomlError('expected a name')
  const ch = cur.s[cur.i]
  if (ch === '"') return parseBasicString(cur)
  if (ch === "'") return parseLiteralString(cur)
  const start = cur.i
  while (cur.i < cur.len && BARE_CHAR_RE.test(cur.s[cur.i])) cur.i++
  if (cur.i === start) throw new TomlError('expected a name')
  return cur.s.slice(start, cur.i)
}

function parseDottedName(cur) {
  const names = [parseName(cur)]
  while (true) {
    const save = cur.i
    skip(cur)
    if (cur.i < cur.len && cur.s[cur.i] === '.') {
      cur.i++
      skip(cur)
      names.push(parseName(cur))
    } else {
      cur.i = save
      break
    }
  }
  return names
}

// ---- strings -----------------------------------------------------------------

function parseBasicString(cur) {
  cur.i++ // opening quote
  let out = ''
  while (true) {
    if (cur.i >= cur.len) throw new TomlError('unterminated string')
    const ch = cur.s[cur.i]
    if (ch === '"') {
      cur.i++
      return out
    }
    if (ch === '\\') {
      cur.i++
      if (cur.i >= cur.len) throw new TomlError('unterminated string')
      const esc = cur.s[cur.i]
      switch (esc) {
        case '"': out += '"'; cur.i++; break
        case '\\': out += '\\'; cur.i++; break
        case 'n': out += '\n'; cur.i++; break
        case 't': out += '\t'; cur.i++; break
        case 'r': out += '\r'; cur.i++; break
        case '0': out += '\0'; cur.i++; break
        case 'u': {
          const hex = cur.s.slice(cur.i + 1, cur.i + 5)
          if (hex.length !== 4 || !/^[0-9A-Fa-f]{4}$/.test(hex)) {
            throw new TomlError('invalid escape \\u')
          }
          out += String.fromCharCode(parseInt(hex, 16))
          cur.i += 5
          break
        }
        default:
          throw new TomlError('invalid escape \\' + esc)
      }
    } else {
      out += ch
      cur.i++
    }
  }
}

function parseLiteralString(cur) {
  cur.i++ // opening quote
  let out = ''
  while (true) {
    if (cur.i >= cur.len) throw new TomlError('unterminated string')
    const ch = cur.s[cur.i]
    if (ch === "'") {
      cur.i++
      return out
    }
    out += ch
    cur.i++
  }
}

// ---- values -----------------------------------------------------------------

const VALUE_STOP = new Set([' ', '\t', ',', ']', '}'])

function parseValue(cur, path) {
  if (cur.i >= cur.len) throw new TomlError('expected a value')
  const ch = cur.s[cur.i]
  if (ch === '"') return { kind: 'string', value: parseBasicString(cur) }
  if (ch === "'") return { kind: 'string', value: parseLiteralString(cur) }
  if (ch === '[') return parseArray(cur, path)
  if (ch === '{') return parseInlineTable(cur, path)
  if (ch === ',' || ch === ']' || ch === '}') throw new TomlError('expected a value')

  const start = cur.i
  while (cur.i < cur.len && !VALUE_STOP.has(cur.s[cur.i])) cur.i++
  const token = cur.s.slice(start, cur.i)
  if (token === 'true') return { kind: 'boolean', value: true }
  if (token === 'false') return { kind: 'boolean', value: false }
  if (INT_RE.test(token)) return { kind: 'integer', value: Number(token.replace(/_/g, '')) }
  if ((token.includes('.') || /[eE]/.test(token)) && FLOAT_RE.test(token)) {
    return { kind: 'float', value: Number(token.replace(/_/g, '')) }
  }
  throw new TomlError('invalid value ' + token)
}

function parseArray(cur, path) {
  cur.i++ // '['
  const items = []
  skip(cur)
  if (cur.i < cur.len && cur.s[cur.i] === ']') {
    cur.i++
    return { kind: 'array', items }
  }
  let idx = 0
  while (true) {
    skip(cur)
    if (cur.i >= cur.len) throw new TomlError('unterminated array')
    const val = parseValue(cur, path.concat([indexSeg(idx)]))
    items.push(val)
    idx++
    skip(cur)
    if (cur.i >= cur.len) throw new TomlError('unterminated array')
    const ch = cur.s[cur.i]
    if (ch === ',') {
      cur.i++
      skip(cur)
      if (cur.i < cur.len && cur.s[cur.i] === ']') {
        cur.i++
        break
      }
      continue
    } else if (ch === ']') {
      cur.i++
      break
    } else {
      throw new TomlError('unterminated array')
    }
  }
  return { kind: 'array', items }
}

function parseInlineTable(cur, path) {
  cur.i++ // '{'
  const table = newTable()
  skip(cur)
  if (cur.i < cur.len && cur.s[cur.i] === '}') {
    cur.i++
    return table
  }
  while (true) {
    skip(cur)
    if (cur.i >= cur.len) throw new TomlError('unterminated inline table')
    const names = parseDottedName(cur)
    skip(cur)
    if (cur.i >= cur.len || cur.s[cur.i] !== '=') throw new TomlError('expected = in an inline table')
    cur.i++
    skip(cur)
    const pairPath = path.concat(names.map(keySeg))
    const val = parseValue(cur, pairPath)
    assignKeyPath(table, names, val, path)
    skip(cur)
    if (cur.i >= cur.len) throw new TomlError('unterminated inline table')
    const ch = cur.s[cur.i]
    if (ch === ',') {
      cur.i++
      continue
    } else if (ch === '}') {
      cur.i++
      break
    } else {
      throw new TomlError('unterminated inline table')
    }
  }
  return table
}

// ---- structural assignment ---------------------------------------------------

/** Walks through an existing name that must resolve to a table, creating it if absent. */
function stepIntoTable(parentTable, name, parentPath) {
  const existing = parentTable.children.get(name)
  const segs = parentPath.concat([keySeg(name)])
  if (existing === undefined) {
    const t = newTable()
    parentTable.children.set(name, t)
    return { table: t, path: segs }
  }
  if (existing.kind === 'table') {
    return { table: existing, path: segs }
  }
  if (existing.kind === 'array-of-tables') {
    const idx = existing.items.length - 1
    return { table: existing.items[idx], path: segs.concat([indexSeg(idx)]) }
  }
  throw new TomlError(joinPath(segs) + ' is not a table')
}

/** Assigns `value` at `names` (relative to `table`, whose own path is `basePath`). */
function assignKeyPath(table, names, value, basePath) {
  let node = table
  let path = basePath
  for (let k = 0; k < names.length - 1; k++) {
    const step = stepIntoTable(node, names[k], path)
    node = step.table
    path = step.path
  }
  const lastName = names[names.length - 1]
  const finalPath = path.concat([keySeg(lastName)])
  if (node.children.has(lastName)) {
    throw new TomlError('key ' + joinPath(finalPath) + ' is defined twice')
  }
  node.children.set(lastName, value)
}

// ---- headers -----------------------------------------------------------------

function handleHeader(cur, state) {
  cur.i++ // '['
  let isArray = false
  if (cur.i < cur.len && cur.s[cur.i] === '[') {
    isArray = true
    cur.i++
  }
  skip(cur)
  if (cur.i >= cur.len) throw new TomlError('unterminated table header')
  const names = parseDottedName(cur)
  skip(cur)
  if (cur.i >= cur.len || cur.s[cur.i] !== ']') throw new TomlError('unterminated table header')
  cur.i++
  if (isArray) {
    if (cur.i >= cur.len || cur.s[cur.i] !== ']') throw new TomlError('unterminated table header')
    cur.i++
  }
  skip(cur)
  if (cur.i < cur.len) throw new TomlError('trailing text after a table header')

  let node = state.currentTable
  let path = state.currentPath
  for (let k = 0; k < names.length - 1; k++) {
    const step = stepIntoTable(node, names[k], path)
    node = step.table
    path = step.path
  }
  const lastName = names[names.length - 1]
  const finalPath = path.concat([keySeg(lastName)])
  const existing = node.children.get(lastName)

  if (isArray) {
    let arr
    if (existing === undefined) {
      arr = { kind: 'array-of-tables', items: [] }
      node.children.set(lastName, arr)
    } else if (existing.kind === 'array-of-tables') {
      arr = existing
    } else {
      throw new TomlError(joinPath(finalPath) + ' is not an array of tables')
    }
    const fresh = newTable()
    arr.items.push(fresh)
    const idx = arr.items.length - 1
    state.currentTable = fresh
    state.currentPath = finalPath.concat([indexSeg(idx)])
  } else {
    let target
    if (existing === undefined) {
      target = newTable()
      node.children.set(lastName, target)
    } else if (existing.kind === 'table') {
      target = existing
    } else {
      throw new TomlError(joinPath(finalPath) + ' is not a table')
    }
    if (target.headerDefined) {
      throw new TomlError('table ' + joinPath(finalPath) + ' is defined twice')
    }
    target.headerDefined = true
    state.currentTable = target
    state.currentPath = finalPath
  }
}

// ---- assignment lines ----------------------------------------------------------

function handleAssignment(cur, state) {
  const names = parseDottedName(cur)
  skip(cur)
