import { newTable } from './nodes.js'
import { keySeg, indexSeg, joinPath } from './path.js'

const INT_RE = /^[+-]?[0-9]+(_[0-9]+)*$/
const FLOAT_RE = /^[+-]?[0-9]+(_[0-9]+)*(\.[0-9]+(_[0-9]+)*)?([eE][+-]?[0-9]+(_[0-9]+)*)?$/
const BARE_CHAR_RE = /[A-Za-z0-9_-]/

/**
 * Parses the whole document (already split into lines, with the empty tail
 * a trailing newline leaves already dropped) and returns the root table.
 * Throws a `TomlError` with `.line` set to the 1-based offending line.
 */
export function parseDocument(lines) {
  const root = newTable()
  const state = { currentTable: root, currentPath: [] }
  for (let i = 0; i < lines.length; i++) {
    try {
      processLine(lines[i], state)
    } catch (err) {
      if (err instanceof TomlError) {
        err.line = i + 1
      }
      throw err
    }
  }
  return root
}

// ---- line-level cursor helpers -------------------------------------------

function makeCursor(s) {
  return { s, i: 0, len: s.length }
}

/** Skips spaces/tabs, then treats a `#`/`;` outside a quote as "nothing more on this line". */
function skip(cur) {
  while (cur.i < cur.len && (cur.s[cur.i] === ' ' || cur.s[cur.i] === '\t')) cur.i++
  if (cur.i < cur.len && (cur.s[cur.i] === '#' || cur.s[cur.i] === ';')) cur.i = cur.len
}

function processLine(line, state) {
  const cur = makeCursor(line)
  skip(cur)
  if (cur.i >= cur.len) return // blank or comment-only line contributes nothing
  if (cur.s[cur.i] === '[') {
    handleHeader(cur, state)
  } else {
    handleAssignment(cur, state)
  }
}

// ---- names -----------------------------------------------------------------

function parseName(cur) {
  if (cur.i >= cur.len) throw new TomlError('expected a name')
  const ch = cur.s[cur.i]
  if (ch === '"') return parseBasicString(cur)
  if (ch === "'") return parseLiteralString(cur)
  const start = cur.i
  while (cur.i < cur.len && BARE_CHAR_RE.test(cur.s[cur.i])) cur.i++
  if (cur.i === start) throw new TomlError('expected a name')
  return cur.s.slice(start, cur.i)
}

function parseDottedName(cur) {
  const names = [parseName(cur)]
  while (true) {
    const save = cur.i
    skip(cur)
    if (cur.i < cur.len && cur.s[cur.i] === '.') {
      cur.i++
      skip(cur)
      names.push(parseName(cur))
    } else {
      cur.i = save
      break
    }
  }
  return names
}

// ---- strings -----------------------------------------------------------------

function parseBasicString(cur) {
  cur.i++ // opening quote
  let out = ''
  while (true) {
    if (cur.i >= cur.len) throw new TomlError('unterminated string')
    const ch = cur.s[cur.i]
    if (ch === '"') {
      cur.i++
      return out
    }
    if (ch === '\\') {
      cur.i++
      if (cur.i >= cur.len) throw new TomlError('unterminated string')
      const esc = cur.s[cur.i]
      switch (esc) {
        case '"': out += '"'; cur.i++; break
        case '\\': out += '\\'; cur.i++; break
        case 'n': out += '\n'; cur.i++; break
        case 't': out += '\t'; cur.i++; break
        case 'r': out += '\r'; cur.i++; break
        case '0': out += '\0'; cur.i++; break
        case 'u': {
          const hex = cur.s.slice(cur.i + 1, cur.i + 5)
          if (hex.length !== 4 || !/^[0-9A-Fa-f]{4}$/.test(hex)) {
            throw new TomlError('invalid escape \\u')
          }
          out += String.fromCharCode(parseInt(hex, 16))
          cur.i += 5
          break
        }
        default:
          throw new TomlError('invalid escape \\' + esc)
      }
    } else {
      out += ch
      cur.i++
    }
  }
}

function parseLiteralString(cur) {
  cur.i++ // opening quote
  let out = ''
  while (true) {
    if (cur.i >= cur.len) throw new TomlError('unterminated string')
    const ch = cur.s[cur.i]
    if (ch === "'") {
      cur.i++
      return out
    }
    out += ch
    cur.i++
  }
