const VALUE_STOP = new Set([' ', '\t', ',', ']', '}'])

function parseValue(cur, path) {
  if (cur.i >= cur.len) throw new TomlError('expected a value')
  const ch = cur.s[cur.i]
  if (ch === '"') return { kind: 'string', value: parseBasicString(cur) }
  if (ch === "'") return { kind: 'string', value: parseLiteralString(cur) }
  if (ch === '[') return parseArray(cur, path)
  if (ch === '{') return parseInlineTable(cur, path)
  if (ch === ',' || ch === ']' || ch === '}') throw new TomlError('expected a value')

  const start = cur.i
  while (cur.i < cur.len && !VALUE_STOP.has(cur.s[cur.i])) cur.i++
  const token = cur.s.slice(start, cur.i)
  if (token === 'true') return { kind: 'boolean', value: true }
  if (token === 'false') return { kind: 'boolean', value: false }
  if (INT_RE.test(token)) return { kind: 'integer', value: Number(token.replace(/_/g, '')) }
  if ((token.includes('.') || /[eE]/.test(token)) && FLOAT_RE.test(token)) {
    return { kind: 'float', value: Number(token.replace(/_/g, '')) }
  }
  throw new TomlError('invalid value ' + token)
}

function parseArray(cur, path) {
  cur.i++ // '['
  const items = []
  skip(cur)
  if (cur.i < cur.len && cur.s[cur.i] === ']') {
    cur.i++
    return { kind: 'array', items }
  }
