    skip(cur)
    if (cur.i >= cur.len) throw new TomlError('unterminated inline table')
    const names = parseDottedName(cur)
    skip(cur)
    if (cur.i >= cur.len || cur.s[cur.i] !== '=') throw new TomlError('expected = in an inline table')
