    if (ch === ',') {
      cur.i++
      continue
    } else if (ch === '}') {
      cur.i++
      break
    } else {
      throw new TomlError('unterminated inline table')
    }
  }
  return table
}

// ---- structural assignment ---------------------------------------------------

/** Walks through an existing name that must resolve to a table, creating it if absent. */
function stepIntoTable(parentTable, name, parentPath) {
  const existing = parentTable.children.get(name)
  const segs = parentPath.concat([keySeg(name)])
  if (existing === undefined) {
    const t = newTable()
    parentTable.children.set(name, t)
    return { table: t, path: segs }
  }
  if (existing.kind === 'table') {
    return { table: existing, path: segs }
  }
  if (existing.kind === 'array-of-tables') {
    const idx = existing.items.length - 1
    return { table: existing.items[idx], path: segs.concat([indexSeg(idx)]) }
  }
  throw new TomlError(joinPath(segs) + ' is not a table')
}

/** Assigns `value` at `names` (relative to `table`, whose own path is `basePath`). */
function assignKeyPath(table, names, value, basePath) {
  let node = table
  let path = basePath
  for (let k = 0; k < names.length - 1; k++) {
    const step = stepIntoTable(node, names[k], path)
    node = step.table
    path = step.path
  }
  const lastName = names[names.length - 1]
  const finalPath = path.concat([keySeg(lastName)])
  if (node.children.has(lastName)) {
    throw new TomlError('key ' + joinPath(finalPath) + ' is defined twice')
  }
  node.children.set(lastName, value)
}

// ---- headers -----------------------------------------------------------------

function handleHeader(cur, state) {
  cur.i++ // '['
  let isArray = false
  if (cur.i < cur.len && cur.s[cur.i] === '[') {
    isArray = true
    cur.i++
  }
  skip(cur)
  if (cur.i >= cur.len) throw new TomlError('unterminated table header')
  const names = parseDottedName(cur)
  skip(cur)
  if (cur.i >= cur.len || cur.s[cur.i] !== ']') throw new TomlError('unterminated table header')
  cur.i++
  if (isArray) {
    if (cur.i >= cur.len || cur.s[cur.i] !== ']') throw new TomlError('unterminated table header')
    cur.i++
  }
  skip(cur)
  if (cur.i < cur.len) throw new TomlError('trailing text after a table header')

  let node = state.currentTable
  let path = state.currentPath
  for (let k = 0; k < names.length - 1; k++) {
    const step = stepIntoTable(node, names[k], path)
    node = step.table
    path = step.path
  }
  const lastName = names[names.length - 1]
  const finalPath = path.concat([keySeg(lastName)])
  const existing = node.children.get(lastName)

  if (isArray) {
    let arr
    if (existing === undefined) {
      arr = { kind: 'array-of-tables', items: [] }
      node.children.set(lastName, arr)
    } else if (existing.kind === 'array-of-tables') {
      arr = existing
    } else {
      throw new TomlError(joinPath(finalPath) + ' is not an array of tables')
    }
    const fresh = newTable()
    arr.items.push(fresh)
    const idx = arr.items.length - 1
    state.currentTable = fresh
    state.currentPath = finalPath.concat([indexSeg(idx)])
  } else {
    let target
    if (existing === undefined) {
      target = newTable()
      node.children.set(lastName, target)
    } else if (existing.kind === 'table') {
      target = existing
    } else {
      throw new TomlError(joinPath(finalPath) + ' is not a table')
    }
    if (target.headerDefined) {
      throw new TomlError('table ' + joinPath(finalPath) + ' is defined twice')
    }
    target.headerDefined = true
    state.currentTable = target
    state.currentPath = finalPath
  }
}

// ---- assignment lines ----------------------------------------------------------

function handleAssignment(cur, state) {
  const names = parseDottedName(cur)
  skip(cur)
  if (cur.i >= cur.len || cur.s[cur.i] !== '=') throw new TomlError('expected key = value')
  cur.i++
  skip(cur)
  const fullPath = state.currentPath.concat(names.map(keySeg))
  const value = parseValue(cur, fullPath)
  skip(cur)
  if (cur.i < cur.len) throw new TomlError('trailing text after a value')
  assignKeyPath(state.currentTable, names, value, state.currentPath)
}
