 * Renders a parsed document (see nodes.js) as canonical JSON or as the
 * `keys` listing.
 */

function indentOf(n) {
  return ' '.repeat(n)
}

function stringifyNode(node, indent) {
  switch (node.kind) {
    case 'string':
    case 'integer':
    case 'float':
    case 'boolean':
      return JSON.stringify(node.value)
    case 'array':
    case 'array-of-tables':
      return stringifyArray(node.items, indent)
    case 'table':
      return stringifyTable(node, indent)
    default:
      throw new Error('unreachable node kind ' + node.kind)
  }
}

function stringifyArray(items, indent) {
  if (items.length === 0) return '[]'
  const inner = indent + 2
  const parts = items.map((it) => indentOf(inner) + stringifyNode(it, inner))
  return '[\n' + parts.join(',\n') + '\n' + indentOf(indent) + ']'
}

function stringifyTable(table, indent) {
  const keys = Array.from(table.children.keys()).sort()
  if (keys.length === 0) return '{}'
  const inner = indent + 2
  const parts = keys.map(
    (k) => indentOf(inner) + JSON.stringify(k) + ': ' + stringifyNode(table.children.get(k), inner)
  )
  return '{\n' + parts.join(',\n') + '\n' + indentOf(indent) + '}'
}

export function toJson(root) {
  return stringifyNode(root, 0) + '\n'
}

function typeName(node) {
  if (node.kind === 'table') return 'table'
  if (node.kind === 'array' || node.kind === 'array-of-tables') return 'array'
  return node.kind
}

function emit(node, path, lines) {
  if (node.kind === 'table') {
    const keys = Array.from(node.children.keys()).sort()
    for (const k of keys) {
      const child = node.children.get(k)
      const childPath = path === '' ? k : path + '.' + k
      lines.push(childPath + ' ' + typeName(child))
      emit(child, childPath, lines)
    }
  } else if (node.kind === 'array' || node.kind === 'array-of-tables') {
    node.items.forEach((item, i) => {
      const childPath = path + '[' + i + ']'
      lines.push(childPath + ' ' + typeName(item))
      emit(item, childPath, lines)
    })
  }
}

export function toKeys(root) {
  const lines = []
  emit(root, '', lines)
  return lines.length === 0 ? '' : lines.join('\n') + '\n'
}
"}

